 * The configuration document parser. `parseDocument` turns the text of a
 * document into a tree of tagged nodes, or throws a `ParseError` carrying the
 * reason and the one-based number of the line that failed.
 */

export class ParseError extends Error {
  constructor(reason, line) {
    super(reason)
    this.reason = reason
    this.line = line
  }
}

export function newTable() {
  return { t: 'table', map: new Map(), header: false }
}

function newArray(aot) {
  return { t: 'array', v: [], aot }
}

const NAME = /^[A-Za-z0-9_-]+/
const DIG = '[0-9]+(?:_[0-9]+)*'
const INTEGER = new RegExp(`^[+-]?${DIG}$`)
const FLOAT = new RegExp(`^[+-]?${DIG}(?:\\.${DIG})?(?:[eE][+-]?${DIG})?$`)
const FLOAT_TAIL = new RegExp(`^[+-]?${DIG}(?:\\.${DIG}|[eE][+-]?${DIG})`)

function joinKey(path, name) {
  return path ? `${path}.${name}` : name
}

function bareValue(text) {
  if (text === 'true') return { t: 'boolean', v: true }
  if (text === 'false') return { t: 'boolean', v: false }
  const plain = text.replace(/_/g, '')
  if (INTEGER.test(text)) return { t: 'integer', v: Number(plain) }
  if (FLOAT.test(text) && FLOAT_TAIL.test(text)) return { t: 'float', v: Number(plain) }
  throw new ParseError(`invalid value ${text}`)
}

/** A cursor over a single line of the document. */
class Cursor {
  constructor(s) {
    this.s = s
    this.i = 0
  }

  err(reason) {
    throw new ParseError(reason)
  }

  eof() {
    return this.i >= this.s.length
  }

  peek() {
    return this.s[this.i]
  }

  ws() {
    while (this.i < this.s.length && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** True where the rest of the line is empty or is a comment. */
  atEnd() {
    if (this.eof()) return true
    const c = this.s[this.i]
    return c === '#' || c === ';'
  }

  parseString() {
    const quote = this.s[this.i]
    this.i++
    let out = ''
    if (quote === "'") {
      for (;;) {
        if (this.eof()) this.err('unterminated string')
        const c = this.s[this.i++]
        if (c === "'") return out
        out += c
      }
    }
    for (;;) {
      if (this.eof()) this.err('unterminated string')
      const c = this.s[this.i++]
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      if (this.eof()) this.err('unterminated string')
      const e = this.s[this.i++]
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const hex = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.err('invalid escape \\u')
        this.i += 4
        out += String.fromCharCode(parseInt(hex, 16))
      } else this.err(`invalid escape \\${e}`)
    }
  }

  parseName() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.parseString()
    const m = NAME.exec(this.s.slice(this.i))
    if (!m) this.err('expected a name')
    this.i += m[0].length
    return m[0]
  }

  parseDottedName() {
    const names = [this.parseName()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
        this.ws()
        names.push(this.parseName())
      } else {
        this.i = save
        return names
      }
    }
  }

  parseValue(path) {
    if (this.atEnd()) this.err('expected a value')
    const c = this.peek()
    if (c === '"' || c === "'") return { t: 'string', v: this.parseString() }
    if (c === '[') return this.parseArray(path)
    if (c === '{') return this.parseInlineTable(path)
    if (c === ',' || c === ']' || c === '}') this.err('expected a value')
    let j = this.i
    while (j < this.s.length && !' \t,]};'.includes(this.s[j])) j++
    const text = this.s.slice(this.i, j)
    this.i = j
    return bareValue(text)
  }

  parseArray(path) {
    this.i++
    const node = newArray(false)
    for (;;) {
      this.ws()
      if (this.atEnd()) this.err('unterminated array')
      if (this.peek() === ']') {
        this.i++
        return node
      }
      node.v.push(this.parseValue(`${path}[${node.v.length}]`))
      this.ws()
      if (this.atEnd()) this.err('unterminated array')
      if (this.peek() === ',') this.i++
    }
  }

  parseInlineTable(path) {
    this.i++
    const table = newTable()
    this.ws()
    if (this.peek() === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.err('unterminated inline table')
      const names = this.parseDottedName()
      this.ws()
      if (this.peek() !== '=') this.err('expected = in an inline table')
      this.i++
      this.ws()
      const value = this.parseValue(names.reduce(joinKey, path))
      assign(table, names, value, path)
      this.ws()
      if (this.atEnd()) this.err('unterminated inline table')
      if (this.peek() === ',') {
        this.i++
        continue
      }
      if (this.peek() === '}') {
        this.i++
        return table
      }
    }
  }
}

/** Walks the names before the last one, making the tables they pass through. */
function walkInto(table, names, basePath) {
  let cur = table
  let path = basePath
  for (let k = 0; k < names.length - 1; k++) {
    const name = names[k]
    path = joinKey(path, name)
    let node = cur.map.get(name)
    if (node === undefined) {
      node = newTable()
      cur.map.set(name, node)
    }
    if (node.t === 'table') cur = node
    else if (node.t === 'array' && node.aot && node.v.length > 0) cur = node.v[node.v.length - 1]
    else throw new ParseError(`${path} is not a table`)
  }
  return { table: cur, path }
}

function assign(table, names, value, basePath) {
  const { table: cur, path } = walkInto(table, names, basePath)
  const name = names[names.length - 1]
  const full = joinKey(path, name)
  if (cur.map.has(name)) throw new ParseError(`key ${full} is defined twice`)
  cur.map.set(name, value)
}

function headerTable(root, names) {
  const { table: cur, path } = walkInto(root, names, '')
  const name = names[names.length - 1]
  const full = joinKey(path, name)
  let node = cur.map.get(name)
  if (node === undefined) {
    node = newTable()
    cur.map.set(name, node)
  }
  if (node.t !== 'table') throw new ParseError(`${full} is not a table`)
  if (node.header) throw new ParseError(`table ${full} is defined twice`)
  node.header = true
  return node
}

function arrayTable(root, names) {
  const { table: cur, path } = walkInto(root, names, '')
  const name = names[names.length - 1]
  const full = joinKey(path, name)
  let node = cur.map.get(name)
  if (node === undefined) {
    node = newArray(true)
    cur.map.set(name, node)
  }
  if (node.t !== 'array' || !node.aot) throw new ParseError(`${full} is not an array of tables`)
  const fresh = newTable()
  node.v.push(fresh)
  return fresh
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parseDocument(text) {
  const root = newTable()
  let current = root
  let currentPath = ''
  const lines = splitLines(text)
  for (let n = 0; n < lines.length; n++) {
    try {
      const p = new Cursor(lines[n])
      p.ws()
      if (p.atEnd()) continue
      if (p.peek() === '[') {
        p.i++
        let aot = false
        if (p.peek() === '[') {
          aot = true
          p.i++
        }
        p.ws()
        const names = p.parseDottedName()
        p.ws()
        if (p.peek() !== ']') p.err('unterminated table header')
        p.i++
        if (aot) {
          if (p.peek() !== ']') p.err('unterminated table header')
          p.i++
        }
        p.ws()
        if (!p.atEnd()) p.err('trailing text after a table header')
        current = aot ? arrayTable(root, names) : headerTable(root, names)
        currentPath = names.join('.')
      } else {
        const names = p.parseDottedName()
        p.ws()
        if (p.peek() !== '=') p.err('expected key = value')
        p.i++
        p.ws()
        const value = p.parseValue(names.reduce(joinKey, currentPath))
        p.ws()
        if (!p.atEnd()) p.err('trailing text after a value')
        assign(current, names, value, currentPath)
      }
    } catch (e) {
      if (e instanceof ParseError && e.line === undefined) e.line = n + 1
      throw e
    }
  }
  return root
}
