{"file_path":"src/format.js","content":"/**
 * The two renderings of a parsed document: canonical JSON, and the flat listing
 * of every path below the root with its type.
 */

/** Compares two strings by code point rather than by UTF-16 code unit. */
export function compareKeys(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedEntries(table) {
  return Array.from(table.map.keys())
    .sort(compareKeys)
    .map((k) => [k, table.map.get(k)])
}

function render(node, indent) {
  const pad = ' '.repeat(indent)
  const inner = ' '.repeat(indent + 2)
  if (node.t === 'table') {
    const entries = sortedEntries(node)
    if (entries.length === 0) return '{}'
    const parts = entries.map(([k, v]) => `${inner}${JSON.stringify(k)}: ${render(v, indent + 2)}`)
    return `{\n${parts.join(',\n')}\n${pad}}`
  }
  if (node.t === 'array') {
    if (node.v.length === 0) return '[]'
    const parts = node.v.map((v) => `${inner}${render(v, indent + 2)}`)
    return `[\n${parts.join(',\n')}\n${pad}]`
  }
  if (node.t === 'string') return JSON.stringify(node.v)
  if (node.t === 'boolean') return node.v ? 'true' : 'false'
  return JSON.stringify(node.v)
}

export function toJson(root) {
  return `${render(root, 0)}\n`
}

export function toKeys(root) {
  const out = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const [k, v] of sortedEntries(node)) {
        const p = path ? `${path}.${k}` : k
        out.push(`${p} ${v.t}\n`)
        walk(v, p)
      }
    } else if (node.t === 'array') {
      for (let i = 0; i < node.v.length; i++) {
        const p = `${path}[${i}]`
        out.push(`${p} ${node.v[i].t}\n`)
        walk(node.v[i], p)
      }
    }
  }
  walk(root, '')
  return out.join('')
}
